// As I am only a beginner with Shadertoy, I do most of my work in materials in Unreal Engine. 
// I started with an article from @patricigv in the "The Book of Shaders", section: "Cellular Noise", title: "CellularNoise"   
// All I really did was give the cells more of a 3D shape.


const float ScaleFactor = 5.0;        

vec2 random2( vec2 p ) 
{
    return fract(sin(vec2(dot(p,vec2(127.1,311.7)),dot(p,vec2(269.5,183.3))))*43758.5453);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 st = fragCoord.xy/iResolution.xy;
    vec2 uv = st;
    st.x *= iResolution.x/iResolution.y;

    vec3 color = vec3(0.0,0.0,0.0);

    st *= ScaleFactor;

    // Tile the space
    vec2 i_st = floor(st); 
    vec2 f_st = fract(st);

    float m_dist = 1.0;  // minimum distance

    for (int y= -1; y <= 1; y++) 
    {
        for (int x= -1; x <= 1; x++) 
        {
            // Neighbor place in the grid
            vec2 neighbor = vec2(float(x),float(y));

            // Random position from current + neighbor place in the grid
            vec2 pt = random2(i_st + neighbor);

			// Animate the point
            pt = 0.5 + 0.5*sin(iTime + 6.2831*pt);  //here

			// vector between the pixel and the point
            vec2 diff = neighbor + pt - f_st;

            // Distance to the point
            float dist = length(diff);

            // Keep the closer distance
            m_dist = min(m_dist, dist);
        }
    }


    // Draw the min distance (distance field)
    color += m_dist;

    color = mix(vec3(0.0f), color, color * 2.0f);   // try to give sharper lines

    // Draw cell center
    color.g = m_dist * 1.5;              
    color.b = m_dist * 1.4;              

    // split screen
    if (uv.x < 0.5)
    {
        color = (1.0 - color);               
    }    

    color = pow(color, vec3(2.0));   

    // Output to screen
    fragColor = vec4(color,1.0);
}
